'use strict';
const COURIER_STORE='teztaom-seller-v1';
function courierDefaults(){return [{id:'c1',name:'Jasur Aliyev',phone:'+998 90 000 11 22',vehicle:'Velosiped',active:true,online:false},{id:'c2',name:'Kamola Saidova',phone:'+998 91 000 33 44',vehicle:'Skuter',active:true,online:false}];}
function deliveryReady(o){return typeof o.deliveryAddress==='string'&&o.deliveryAddress.trim().length>=5&&Number.isFinite(o.deliveryFee)&&o.deliveryFee>=0&&o.deliveryFee<=1000000;}
function deliveryStage(o){return o.delivery?.status||'unassigned';}
function deliveryBadge(o){const stage=deliveryStage(o);const text={assigned:'Kuryer biriktirilgan',picked_up:'Yetkazilmoqda',delivered:'Yetkazildi',returned:'Restoranga qaytarilgan'}[stage];return text?`<span class="tag ${stage==='delivered'?'success':'warning'}">${text}</span>${o.delivery.issue?'<span class="tag danger">Muammo belgilangan</span>':''}`:'';}
function deliveryDataValid(o){if(!o)return false;if(o.deliveryFee!==undefined&&(!Number.isFinite(o.deliveryFee)||o.deliveryFee<0||o.deliveryFee>1000000))return false;if(o.deliveryAddress!==undefined&&(typeof o.deliveryAddress!=='string'||o.deliveryAddress.length>250))return false;if(!o.delivery)return true;const d=o.delivery;return typeof d.courierId==='string'&&Number.isFinite(d.fee)&&d.fee>=0&&d.fee<=1000000&&Number.isFinite(d.assignedAt)&&['assigned','picked_up','delivered','returned'].includes(d.status)&&(d.status==='assigned'?o.status==='ready':o.status===(d.status==='returned'?'returned':'completed')&&Number.isFinite(d.pickedUpAt))&&(d.status!=='delivered'||Number.isFinite(d.deliveredAt))&&(d.status!=='returned'||Number.isFinite(d.returnedAt))&&(d.issue===undefined||typeof d.issue==='string'&&d.issue.length<=500);}
function courierStateValid(s){return s?.version===1&&!!s.profile&&Array.isArray(s.orders)&&s.orders.every(deliveryDataValid)&&Array.isArray(s.products)&&Array.isArray(s.branches)&&Array.isArray(s.staff)&&(!s.couriers||Array.isArray(s.couriers)&&s.couriers.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&typeof c.phone==='string'&&typeof c.active==='boolean'&&typeof c.online==='boolean'))&&courierWorkDataValid(s);}
function courierWorkDataValid(s){const money=e=>typeof e.id==='string'&&typeof e.courierId==='string'&&Number.isFinite(e.at)&&Number.isFinite(e.amount)&&e.amount>0;return (s.courierExtras===undefined||Array.isArray(s.courierExtras)&&s.courierExtras.every(e=>money(e)&&['bonus','tip'].includes(e.type)&&typeof e.orderId==='string'))&&(s.courierLedger===undefined||Array.isArray(s.courierLedger)&&s.courierLedger.every(e=>money(e)&&['payout','cash'].includes(e.type)))&&(s.courierArchive===undefined||Array.isArray(s.courierArchive)&&s.courierArchive.every(e=>typeof e.id==='string'&&typeof e.courierId==='string'&&Number.isFinite(e.at)&&['released','cancelled','declined'].includes(e.status)&&deliveryDataValid(e.order)))&&(!s.couriers||s.couriers.every(c=>(c.shifts===undefined||Array.isArray(c.shifts)&&c.shifts.every(x=>Number.isFinite(x.startedAt)&&(!x.endedAt||Number.isFinite(x.endedAt))&&Array.isArray(x.breaks)&&x.breaks.every(b=>Number.isFinite(b.startedAt)&&(!b.endedAt||Number.isFinite(b.endedAt)))))&&(c.declined===undefined||Array.isArray(c.declined)&&c.declined.every(x=>typeof x.orderId==='string'&&Number.isFinite(x.at)))));}
function courierRead(){const raw=localStorage.getItem(COURIER_STORE);const s=raw?JSON.parse(raw):seed();if(!courierStateValid(s))throw Error('Saqlangan ma’lumotlar noto‘g‘ri. Sotuvchi panelidagi zaxira nusxani tekshiring.');return s;}
function courierInitialize(){const s=courierRead();let changed=false;if(!s.couriers){s.couriers=courierDefaults();changed=true;}for(const o of s.orders){if(o.delivery?.status==='assigned'&&!o.delivery.handoffCode){o.delivery.handoffCode=String(100000+Math.floor(Math.random()*900000));changed=true;}}if(changed)localStorage.setItem(COURIER_STORE,JSON.stringify(s));return s;}
function courierActiveOrders(s,id){return s.orders.filter(o=>o.delivery?.courierId===id&&['assigned','picked_up'].includes(deliveryStage(o)));}
function courierPhase(o){return o.delivery?.phase||({assigned:'to_restaurant',picked_up:'to_customer',delivered:'delivered',returned:'returned'}[deliveryStage(o)]||'unassigned');}
function courierWork(c){return c.online?'working':c.workStatus==='break'?'break':'offline';}
function courierSetWork(s,c,status){if(!['working','break','offline'].includes(status))throw Error('Ish holati noto‘g‘ri.');if(status!=='working'&&courierActiveOrders(s,c.id).length)throw Error('Avval faol yetkazishni yakunlang.');const before=courierWork(c);if(before===status)return;c.shifts??=[];let shift=c.shifts.find(x=>!x.endedAt);if(status==='working'&&!shift){shift={id:uid(),startedAt:Date.now(),breaks:[],area:c.area||'Belgilanmagan'};c.shifts.push(shift);}if(before==='break'&&shift?.breaks.at(-1)&&!shift.breaks.at(-1).endedAt)shift.breaks.at(-1).endedAt=Date.now();if(status==='break'&&shift)shift.breaks.push({startedAt:Date.now()});if(status==='offline'&&shift)shift.endedAt=Date.now();c.workStatus=status;c.online=status==='working';if(status!=='working'){c.gpsSharing=false;delete c.location;}}
function courierArchive(s,o,id,status,reason){(s.courierArchive??=[]).push({id:uid(),courierId:id,status,reason:reason||'',at:Date.now(),order:structuredClone(o)});}
function courierIncome(s,id){const delivered=courierHistory(s,id),fees=delivered.reduce((sum,o)=>sum+o.delivery.fee,0),extras=(s.courierExtras||[]).filter(e=>e.courierId===id),bonus=extras.filter(e=>e.type==='bonus').reduce((sum,e)=>sum+e.amount,0),tips=extras.filter(e=>e.type==='tip').reduce((sum,e)=>sum+e.amount,0),ledger=(s.courierLedger||[]).filter(e=>e.courierId===id),paid=ledger.filter(e=>e.type==='payout').reduce((sum,e)=>sum+e.amount,0),cash=delivered.reduce((sum,o)=>sum+(o.delivery.cashCollected||0),0),handed=ledger.filter(e=>e.type==='cash').reduce((sum,e)=>sum+e.amount,0);return {fees,bonus,tips,paid,balance:fees+bonus+tips-paid,cash,handed,cashDue:cash-handed};}
function courierHistory(s,id){return s.orders.filter(o=>o.delivery?.courierId===id&&deliveryStage(o)==='delivered').sort((a,b)=>b.delivery.deliveredAt-a.delivery.deliveredAt);}
function courierEvent(o,type,courierId){(o.deliveryEvents??=[]).push({type,courierId,at:Date.now()});}
function courierApply(s,id,action,orderId,payload={}){
 const c=s.couriers?.find(c=>c.id===id&&c.active);if(!c)throw Error('Faol kuryerni tanlang.');
 if(action==='gps'){if(payload.enabled===false){c.gpsSharing=false;delete c.location;return;}const p=geoPoint(payload.lat,payload.lng);if(!p||!Number.isFinite(payload.accuracy)||payload.accuracy<0||courierWork(c)!=='working')throw Error('GPS nuqtasi yoki ish holati noto‘g‘ri.');c.gpsSharing=true;c.location={...p,accuracy:payload.accuracy,at:Date.now()};return;}if(action==='online'){courierSetWork(s,c,payload.online?'working':'offline');return;}
 if(action==='work'){courierSetWork(s,c,payload.status);return;}
 if(action==='preferences'){if(!['uz','ru'].includes(payload.language))throw Error('Tilni tanlang.');c.preferences={language:payload.language,sound:!!payload.sound,notifications:!!payload.notifications};return;}
 if(action==='schedule'){const area=String(payload.area||'').trim();if(!area||area.length>100||!['Velosiped','Skuter','Avtomobil','Piyoda'].includes(payload.vehicle))throw Error('Hudud va transportni tekshiring.');c.area=area;c.vehicle=payload.vehicle;return;}
 if(action==='extra'||action==='ledger'){const amount=Number(payload.amount);if(!Number.isFinite(amount)||amount<=0||amount>10000000)throw Error('Summani to‘g‘ri kiriting.');if(action==='extra'){if(!['bonus','tip'].includes(payload.type)||!courierHistory(s,id).some(o=>o.id===payload.orderId))throw Error('Yetkazilgan buyurtma va yozuv turini tanlang.');(s.courierExtras??=[]).push({id:uid(),courierId:id,type:payload.type,orderId:payload.orderId,amount,at:Date.now(),demo:true});}else{const income=courierIncome(s,id);if(!['payout','cash'].includes(payload.type)||amount>(payload.type==='cash'?income.cashDue:income.balance))throw Error('Summa mavjud qoldiqdan oshmasin.');(s.courierLedger??=[]).push({id:uid(),courierId:id,type:payload.type,amount,at:Date.now(),demo:true});}return;}
 if(action==='profile'){const name=String(payload.name||'').trim(),phone=String(payload.phone||'').trim();if(!name||name.length>80||!/^\+?[0-9 ()-]{9,25}$/.test(phone)||!['Velosiped','Skuter','Avtomobil','Piyoda'].includes(payload.vehicle))throw Error('Ism, telefon va transportni tekshiring.');Object.assign(c,{name,phone,vehicle:payload.vehicle});return;}
 if(action==='demo'){
  const branch=s.branches.find(b=>b.active),p=s.products.find(p=>p.available);if(!branch||!p)throw Error('Faol filial va sotuvdagi taom kerak.');
  if(s.orders.some(o=>o.courierDemo&&o.status==='ready'&&!o.delivery))throw Error('Tayyor demo buyurtma bor. Avval uni sinab ko‘ring.');
  s.orders.unshift({id:uid(),courierDemo:true,customer:'Sinov mijoz',phone:'+998 90 000 00 00',branch:branch.id,items:[{productId:p.id,name:p.name,qty:1,price:p.price}],status:'ready',created:Date.now(),accepted:Date.now(),readyAt:Date.now(),payment:'Karta',note:'Kuryer oqimini tekshirish uchun demo',deliveryAddress:'Toshkent, Mustaqillik shoh ko‘chasi, 12 (sinov manzili)',deliveryFee:15000,pickupLocation:{lat:41.3111,lng:69.2797},dropoffLocation:{lat:41.3260,lng:69.2920},packageCount:1,distanceKm:3.2,deliveryEtaMinutes:35,deliveryEntrance:'2-eshik (demo)',deliveryFloor:'3-qavat (demo)',deliveryLandmark:'Yashil darvoza (demo)',deliveryNote:'Sinov buyurtma. Haqiqiy yetkazish talab qilinmaydi.'});return;
 }
 const o=s.orders.find(o=>o.id===orderId);if(!o)throw Error('Buyurtma topilmadi.');
 if(action==='decline'){if(o.status!=='ready'||o.delivery)throw Error('Taklif endi mavjud emas.');if((c.declined||[]).some(x=>x.orderId===o.id))throw Error('Taklif allaqachon rad etilgan.');const reason=String(payload.reason||'Boshqa taklifni kutaman').slice(0,200);(c.declined??=[]).push({orderId:o.id,at:Date.now(),reason});courierArchive(s,o,id,'declined',reason);return;}
 if(action==='claim'){
  if(!c.online)throw Error('Avval liniyaga chiqing.');
  if(courierActiveOrders(s,id).length)throw Error('Bir vaqtda bitta faol buyurtma olinadi.');
  if(o.status!=='ready'||o.delivery)throw Error('Buyurtmani boshqa kuryer olgan yoki holati o‘zgargan.');
  if(!deliveryReady(o))throw Error('Sotuvchi yetkazish manzili va haqini to‘ldirishi kerak.');
  if((c.declined||[]).some(x=>x.orderId===o.id))throw Error('Siz bu taklifni rad etgansiz.');
  o.delivery={courierId:id,status:'assigned',phase:'to_restaurant',handoffCode:String(100000+(globalThis.crypto?.getRandomValues?crypto.getRandomValues(new Uint32Array(1))[0]%900000:Math.floor(Math.random()*900000))),assignedAt:Date.now(),fee:o.deliveryFee,...(Number.isFinite(o.deliveryEtaMinutes)&&o.deliveryEtaMinutes>0?{dueAt:Date.now()+o.deliveryEtaMinutes*60000}:{})};courierEvent(o,'assigned',id);return;
 }
 if(o.delivery?.courierId!==id)throw Error('Bu buyurtma boshqa kuryerga tegishli.');
 if(action==='arrive-restaurant'){if(o.delivery.status!=='assigned'||courierPhase(o)!=='to_restaurant')throw Error('Restoranga borish bosqichi yakunlangan.');o.delivery.phase='at_restaurant';o.delivery.arrivedRestaurantAt=Date.now();courierEvent(o,'at_restaurant',id);return;}
 if(action==='arrive-customer'){if(o.delivery.status!=='picked_up'||courierPhase(o)!=='to_customer')throw Error('Avval buyurtmani olib keting.');o.delivery.phase='at_customer';o.delivery.arrivedCustomerAt=Date.now();courierEvent(o,'at_customer',id);return;}
 if(action==='cancel'){if(o.delivery.status!=='assigned'||o.status!=='ready')throw Error('Olib ketilgan buyurtma uchun qaytarish oqimidan foydalaning.');const reason=String(payload.reason||'').trim();if(reason.length<3||reason.length>500)throw Error('Bekor qilish sababini yozing.');courierArchive(s,o,id,'cancelled',reason);courierEvent(o,'cancelled',id);delete o.delivery;return;}
 if(action==='return'){if(o.delivery.status!=='picked_up'||payload.returnConfirmed!==true)throw Error('Buyurtmani restoranga qaytarganingizni tasdiqlang.');const reason=String(payload.reason||'').trim();if(reason.length<3||reason.length>500)throw Error('Qaytarish sababini yozing.');o.status='returned';o.returned=Date.now();Object.assign(o.delivery,{status:'returned',phase:'returned',returnedAt:Date.now(),returnReason:reason});courierEvent(o,'returned',id);return;}
 if(action==='release'){
  if(deliveryStage(o)!=='assigned'||o.status!=='ready')throw Error('Olib ketilgan buyurtmani qaytarib bo‘lmaydi.');
  courierArchive(s,o,id,'released','Olib ketilmagan taklif qaytarildi');courierEvent(o,'released',id);delete o.delivery;return;
 }
 if(action==='pickup'){
  if(deliveryStage(o)!=='assigned'||o.status!=='ready')throw Error('Buyurtma hali biriktirilmagan yoki allaqachon olib ketilgan.');
  if(courierPhase(o)!=='at_restaurant')throw Error('Avval restoranga yetib kelganingizni belgilang.');
  if(!o.delivery.handoffConfirmedAt)throw Error('Avval sotuvchi 6 xonali kod bilan topshirishni tasdiqlasin.');
  snapshotCosts(s,o);o.commissionRate=s.profile.commission;o.status='completed';o.completed=Date.now();Object.assign(o.delivery,{status:'picked_up',phase:'to_customer',pickedUpAt:Date.now()});courierEvent(o,'picked_up',id);return;
 }
 if(action==='deliver'){
  if(deliveryStage(o)!=='picked_up'||o.status!=='completed')throw Error('Avval buyurtmani restorandan olib keting.');
  if(courierPhase(o)!=='at_customer')throw Error('Avval mijozga yetib kelganingizni belgilang.');
  if(o.payment==='Naqd'&&payload.cashConfirmed!==true)throw Error('Naqd to‘lov qabul qilinganini tasdiqlang.');
  Object.assign(o.delivery,{status:'delivered',phase:'delivered',deliveredAt:Date.now(),cashCollected:o.payment==='Naqd'?o.items.reduce((sum,i)=>sum+i.qty*i.price,0):0});courierEvent(o,'delivered',id);return;
 }
 if(action==='issue'){
  if(!['assigned','picked_up'].includes(deliveryStage(o)))throw Error('Faqat faol yetkazishda muammo belgilanadi.');
  const text=String(payload.text||'').trim();if(text.length<3||text.length>500)throw Error('Muammoni 3–500 belgi bilan yozing.');o.delivery.issue=text;o.delivery.issueType=String(payload.issueType||'other').slice(0,60);o.delivery.issueAt=Date.now();courierEvent(o,'issue',id);return;
 }
 throw Error('Noma’lum amal.');
}
async function courierTransaction(id,action,orderId,payload){const write=()=>{const s=courierRead();courierApply(s,id,action,orderId,payload);localStorage.setItem(COURIER_STORE,JSON.stringify(s));return s;};return globalThis.navigator?.locks?.request?await navigator.locks.request('lazzat-courier-orders',write):write();}
function sellerApproveHandoff(s,orderId,code){const o=s.orders.find(o=>o.id===orderId);if(!o||!canBranch(s,o.branch)||!sellerViews(s).includes('orders'))throw Error('Bu filial buyurtmasi uchun ruxsat yo‘q.');if(o.status!=='ready'||o.delivery?.status!=='assigned'||courierPhase(o)!=='at_restaurant')throw Error('Kuryer avval restoranga yetib kelganini belgilasin.');if(o.delivery.handoffConfirmedAt)throw Error('Topshirish allaqachon tasdiqlangan.');if(!/^\d{6}$/.test(String(code))||String(code)!==o.delivery.handoffCode)throw Error('Kuryer aytgan 6 xonali kod noto‘g‘ri.');o.delivery.handoffConfirmedAt=Date.now();o.delivery.handoffConfirmedBy=demoActor(s).id;courierEvent(o,'seller_handoff_confirmed',o.delivery.courierId);}
